/**
 * trace-fusion 续发**唤醒路径**测试（2026-11-03 L4 P1-1 要求：必须经真实事件入口）。
 *
 * 事故形状（run tfl-20261103-192444-c7e2）：lane 被中止 ⇒ tab-runs 兜底写
 * `status=unconfirmed, autoGenerated=true` 的 result.json；lane 的 tab 之后继续干活并
 * 最终 `tab-finish` 覆盖**同一个文件**为正式自报。
 *
 * event-bus 旧版按**文件名**永久去重 ⇒ 兜底那次消耗掉文件名后，正式自报不会再通知消费者
 * ⇒ 「lane 后来正式完成就续发下一条」的入口闭合不了（新判据本身正确，但没人叫它）。
 *
 * 本测试从 `onTabResultFile`（真实 watcher 入口）派发两次同一文件，断言第二次能续发。
 * 运行：npm run test:trace-fusion-wake-path
 */
import assert from "node:assert/strict";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, unlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { onTabResultFile, _resetEventBus } from "./event-bus.ts";
import { maybeAutoCollectTraceRun } from "./trace-fusion/supervisor.ts";
import { setCurrentSessionId } from "./identity.ts";

const root = mkdtempSync(join(tmpdir(), "tf-wake-"));
const runsDir = join(root, "trace-fusion-runs");
const tabRunsDir = join(root, "tab-runs");
const timersDir = join(root, "timers-isolated"); // 零写生产计时器目录
mkdirSync(runsDir, { recursive: true });
mkdirSync(tabRunsDir, { recursive: true });

const LANES = ["A", "B", "C"] as const;

const makeRun = (runId: string, tabIds: Record<"A" | "B" | "C", string>) => {
	mkdirSync(join(runsDir, runId), { recursive: true });
	// meta 夹具 = 真实 run 的 meta.json 字段集（tfl-20261103-192444-c7e2 实测清单，R-5）：
	// 缺 repoRoot/baseCommit/shortId/laneDeadlineAt 时续发链会在 dispatchDiagnoseLane 里抛，
	// 测试只能测到「没续发」而测不到续发本身。
	writeFileSync(
		join(runsDir, runId, "meta.json"),
		JSON.stringify({
			runId,
			shortId: "wake",
			status: "running",
			mode: "diagnose",
			task: "wake-path",
			repoRoot: root,
			createdAt: new Date().toISOString(),
			baseCommit: "0000000000000000000000000000000000000000",
			headBefore: "0000000000000000000000000000000000000000",
			runDir: join(runsDir, runId),
			wtDir: "",
			laneWallClockMin: 45,
			laneDeadlineAt: new Date(Date.now() + 45 * 60_000).toISOString(),
			startedAt: new Date().toISOString(),
			lanes: Object.fromEntries(
				LANES.map((lane) => [
					lane,
					{ lane, worktree: join(root, `w${lane}`), tabRunId: tabIds[lane], provision: { junction: [], copied: [], commandOk: true, degraded: false, issues: [] } },
				]),
			),
		}),
		"utf8",
	);
};

/** tab-finish 的真实写盘形状（tab-runs.ts:448 必填 id/taskId/finishedAt；453 拒绝 autoGenerated:false）。 */
const selfResult = (id: string, status = "completed") =>
	writeFileSync(
		join(tabRunsDir, `${id}.result.json`),
		JSON.stringify({ id, taskId: "T1", finishedAt: new Date().toISOString(), status, summary: "自报" }),
		"utf8",
	);

/** tab-runs.ts:349 的兜底形状：unconfirmed + autoGenerated=true。 */
const autoResult = (id: string) =>
	writeFileSync(
		join(tabRunsDir, `${id}.result.json`),
		JSON.stringify({ id, taskId: "T1", finishedAt: new Date().toISOString(), status: "unconfirmed", autoGenerated: true, summary: "回合结束未自报" }),
	);

const liveState = (id: string) =>
	writeFileSync(
		join(tabRunsDir, `${id}.state.json`),
		JSON.stringify({ id, phase: "working", terminal: false, pid: process.pid, heartbeatAt: new Date().toISOString(), turns: 3 }),
		"utf8",
	);

_resetEventBus();

const runId = "tfl-wake";
makeRun(runId, { A: "tabW1", B: "", C: "" });
writeFileSync(join(runsDir, runId, "lane-queue.json"), JSON.stringify({ lanes: ["B", "C"], concurrency: 1 }), "utf8");
liveState("tabW1");

let tabSpawn = 0;
let collectSpawn = 0;
const outcomes: unknown[] = [];

// 本测试必须扮演**派发者**：links.jsonl 里登记 tabW1 由本会话派发（否则完成事件被
// owner-fencing 判成「非派发者」早退，onTabFinished 根本不会被调用，测试测不到唤醒链）。
// 测试身份显式固定（裸进程里没有 session_start，currentSessionId 为空 ⇒ 会话定位拿不到身份）。
const MY = "sess-wake-test-0001";
setCurrentSessionId(MY);
process.env.PI_RUNTIME_DIR = join(root, "runtime"); // journal/mailbox 落临时目录，零写生产
const linksPath = join(root, "links.jsonl");
const linkLine = JSON.stringify({ kind: "tab", targetId: "tabW1", sessionId: MY, at: new Date().toISOString() });
writeFileSync(linksPath, linkLine + String.fromCharCode(10), "utf8");
// ownership 复位：cutover OFF + 清 attachment（与 _test_event_bus.ts 的夹具同口径）
{
	const { attachmentPathFor, setCutover } = await import("./runtime/registry.ts");
	const { masterAddress } = await import("./runtime/address.ts");
	try {
		// 只清 attachment（cutover OFF ⇒ 无 attachment 门）；不得动生产 attachment 的内容
		unlinkSync(attachmentPathFor(masterAddress()));
	} catch { /* 不存在/清不掉 ⇒ 走派发者豁免路径 */ }
	setCutover(false, "test");
}

const opts = {
	runsDir: tabRunsDir,
	linksPath,
	toast: false,
	autoReclaim: false,
	onTabFinished: (tabRunId: string) => {
		const r = maybeAutoCollectTraceRun(tabRunId, {
			runsDir,
			tabRunsDir,
			wtExe: "wt.exe",
			piCli: "pi.js",
			timersDir,
			spawnTab: () => {
				tabSpawn++;
				return { ok: true, pid: 1 } as never;
			},
			spawnWorker: () => {
				collectSpawn++;
			},
		});
		outcomes.push(r);
		return r.isTrace === true && (r.phase === "resumed" || r.phase === "started");
	},
};

// ── 第一次：兜底 unconfirmed（tab 还活着）⇒ 只报进度，不得续发、不得收集 ──
autoResult("tabW1");
onTabResultFile(tabRunsDir, "tabW1.result.json", opts);
assert.equal(outcomes.length, 1, "兜底结果必须通知到消费者（事件入口真实调用 onTabFinished）");
const o1 = outcomes[0] as { phase: string };
assert.equal(o1.phase, "progress", `兜底 unconfirmed + tab 存活 ⇒ progress，实得 ${o1.phase}`);
assert.equal(tabSpawn, 0, "兜底不得释放名额去续发下一条");
assert.equal(collectSpawn, 0, "未全终态不得收集");

// ── 第二次：**同一个文件**被 tab-finish 覆盖成正式自报 ⇒ 必须再次通知并续发 ──
// 旧版在这条路上被文件名去重挡死（本测试即 L4 P1-1 要求的真实入口覆盖）。
selfResult("tabW1");
const secondFired = onTabResultFile(tabRunsDir, "tabW1.result.json", opts);
assert.equal(outcomes.length, 2, "正式自报必须**再次**通知消费者（文件名去重必须按内容指纹，L4 P1-1）");
assert.equal(secondFired, true, "续发成功 ⇒ 消费者应判定为已消费");
const o2 = outcomes[1] as { phase: string };
assert.equal(o2.phase, "resumed", `lane 自报完成后必须续发下一条，实得 ${o2.phase}`);
assert.equal(tabSpawn, 1, "续发必须真的派发一条 lane");

// ── 同一份内容重放仍幂等（R-5：宁可重发不可漏发，但同一事件只处理一次）──
const thirdFired = onTabResultFile(tabRunsDir, "tabW1.result.json", opts);
assert.equal(thirdFired, false, "同一内容指纹重放必须被去重");
assert.equal(tabSpawn, 1, "重放不得二次 spawn");

console.log("trace-fusion wake-path tests passed");
